import requests


def is_valid_vlan(vlan_id):
    """Return True for a usable 802.1Q VLAN ID (1-4094)."""
    if not isinstance(vlan_id, int):
        raise TypeError("vlan_id must be an int")
    return 1 <= vlan_id <= 4094


def short_name(interface):
    """GigabitEthernet1/0/1 -> Gi1/0/1"""
    prefixes = {"GigabitEthernet": "Gi", "TenGigabitEthernet": "Te", "Loopback": "Lo"}
    for long, short in prefixes.items():
        if interface.startswith(long):
            return short + interface[len(long):]
    return interface


def get_hostname(base_url, token):
    """Read the hostname of a device from an inventory API."""
    resp = requests.get(f"{base_url}/api/v1/device",
                        headers={"X-Auth-Token": token}, timeout=10)
    resp.raise_for_status()
    return resp.json()["hostname"]

import unittest
from unittest.mock import patch, Mock

from netutils import is_valid_vlan, short_name, get_hostname


class TestVlan(unittest.TestCase):
    def test_valid_range(self):
        self.assertTrue(is_valid_vlan(1))
        self.assertTrue(is_valid_vlan(4094))

    def test_reserved_and_out_of_range(self):
        for vlan in (0, 4095, 5000):
            with self.subTest(vlan=vlan):
                self.assertFalse(is_valid_vlan(vlan))

    def test_string_raises_type_error(self):
        with self.assertRaises(TypeError):
            is_valid_vlan("10")


class TestShortName(unittest.TestCase):
    def setUp(self):
        self.cases = {"GigabitEthernet1/0/1": "Gi1/0/1", "Loopback0": "Lo0"}

    def test_known_prefixes(self):
        for long, short in self.cases.items():
            self.assertEqual(short_name(long), short)


class TestGetHostname(unittest.TestCase):
    @patch("netutils.requests.get")
    def test_returns_hostname(self, mock_get):
        mock_get.return_value = Mock(status_code=200)
        mock_get.return_value.json.return_value = {"hostname": "edge-sw01"}

        self.assertEqual(get_hostname("https://cc.example.com", "TOKEN"), "edge-sw01")
        mock_get.assert_called_once_with(
            "https://cc.example.com/api/v1/device",
            headers={"X-Auth-Token": "TOKEN"}, timeout=10)


if __name__ == "__main__":
    unittest.main()

